package com.denfense.server.clan;

import com.denfense.server.auth.*;
import com.denfense.server.domain.User;
import com.denfense.server.repository.UserRepository;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.test.web.servlet.MockMvc;
import java.time.*;
import java.util.UUID;
import static com.denfense.server.clan.ClanDtos.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("local")
class ClanServiceTest {
    @Autowired ClanService service;
    @Autowired UserRepository users;
    @Autowired ClanRepository clans;
    @Autowired ClanAccountStateRepository states;
    @Autowired ClanCommandReceiptRepository receipts;
    @Autowired MockMvc mvc;
    @Autowired ObjectMapper json;
    @Autowired LocalDeveloperCredentialRepository localCredentials;
    @MockitoBean ClanClock clock;
    private final Instant now=Instant.parse("2026-11-02T00:00:00Z");
    @BeforeEach void time(){when(clock.now()).thenReturn(now);}
    private long user(int level,int gold) {var u=new User("clan-"+UUID.randomUUID(),"private");u.setAccountLevel(level);u.setGold(gold);return users.saveAndFlush(u).getId();}
    private long user(){return user(10,100000);}
    private String name(){return "클랜"+UUID.randomUUID().toString().substring(0,12);}
    private Command create(String name,JoinMode mode){return new Command(UUID.randomUUID(),Operation.CREATE,null,null,null,name,"소개",null,mode);}
    private long create(long user,JoinMode mode){return service.command(user,create(name(),mode)).clan().clan().clanId();}
    private Command request(long actor,long clan,Operation op,Long target){
        Long revision=switch(op){case APPROVE,REJECT,KICK,PROMOTE,DEMOTE,TRANSFER,UPDATE,DISBAND->service.detail(actor,clan).revision();default->null;};
        return new Command(UUID.randomUUID(),op,clan,target,revision,null,null,null,null);
    }
    private Status act(long actor,long clan,Operation op,Long target){return service.command(actor,request(actor,clan,op,target));}
    private Status join(long actor,long clan){return act(actor,clan,Operation.JOIN,null);}
    private void code(Runnable action,String code){assertThatThrownBy(action::run).isInstanceOfSatisfying(AuthException.class,e->assertThat(e.code()).isEqualTo(code));}
    private void update(long actor,long clan,String notice){service.command(actor,new Command(UUID.randomUUID(),Operation.UPDATE,clan,null,service.detail(actor,clan).revision(),null,"소개",notice,JoinMode.APPROVAL));}

    @Test void creationChargesAccountGoldAndCreatesSingleLeader(){long uid=user();var id=create(uid,JoinMode.OPEN);var s=service.status(uid);assertThat(s.accountGold()).isEqualTo(50000);assertThat(s.role()).isEqualTo(Role.LEADER);assertThat(s.clan().members()).hasSize(1);assertThat(clans.findById(id).orElseThrow().getMemberCount()).isEqualTo(1);}
    @Test void levelNineCannotCreateOrJoin(){long low=user(9,100000),leader=user();long id=create(leader,JoinMode.OPEN);code(()->create(low,JoinMode.OPEN),"CLAN_LEVEL_REQUIRED");code(()->join(low,id),"CLAN_LEVEL_REQUIRED");assertThat(users.findById(low).orElseThrow().getGold()).isEqualTo(100000);}
    @Test void insufficientGoldDoesNotCreateMembership(){long uid=user(10,49999);assertThatThrownBy(()->create(uid,JoinMode.OPEN));assertThat(service.status(uid).clan()).isNull();assertThat(users.findById(uid).orElseThrow().getGold()).isEqualTo(49999);}
    @Test void createRetryIsExactlyOnceAndChangedPayloadRejected(){long uid=user();var c=create(name(),JoinMode.OPEN);var first=service.command(uid,c);var second=service.command(uid,c);assertThat(second.replayed()).isTrue();assertThat(second.accountGold()).isEqualTo(50000);assertThat(second.clan().clan().clanId()).isEqualTo(first.clan().clan().clanId());code(()->service.command(uid,new Command(c.requestId(),c.operation(),null,null,null,name(),"소개",null,c.joinMode())),"CLAN_REQUEST_CONFLICT");}
    @Test void normalizedDuplicateNameDoesNotChargeOrJoin(){long a=user(),b=user();String key="Test"+UUID.randomUUID().toString().substring(0,6);service.command(a,create(key,JoinMode.OPEN));code(()->service.command(b,create(key.toUpperCase(),JoinMode.OPEN)),"CLAN_NAME_TAKEN");assertThat(service.status(b).accountGold()).isEqualTo(100000);assertThat(service.status(b).clan()).isNull();}
    @Test void fullWidthNameIsNormalized(){long a=user(),b=user();String suffix=UUID.randomUUID().toString().substring(0,5);service.command(a,create("ＡＢ"+suffix,JoinMode.OPEN));code(()->service.command(b,create("ab"+suffix,JoinMode.OPEN)),"CLAN_NAME_TAKEN");}
    @Test void compatibilityWhitespaceCannotCreateBlankOrDuplicateNames(){long a=user(),b=user();code(()->service.command(a,create("\u00a0\u00a0",JoinMode.OPEN)),"CLAN_INVALID_REQUEST");String key=name();service.command(a,create(key,JoinMode.OPEN));code(()->service.command(b,create("\u00a0"+key+"\u00a0",JoinMode.OPEN)),"CLAN_NAME_TAKEN");assertThat(service.status(b).accountGold()).isEqualTo(100000);assertThat(service.status(b).clan()).isNull();assertThat(service.search(b,"\u00a0"+key+"\u00a0",0,20).clans()).hasSize(1);}
    @Test void membershipCannotBeDuplicated(){long a=user(),b=user(),c=user();long one=create(a,JoinMode.OPEN),two=create(b,JoinMode.OPEN);join(c,one);code(()->join(c,two),"CLAN_ALREADY_JOINED");code(()->create(c,JoinMode.OPEN),"CLAN_ALREADY_JOINED");}
    @Test void approvalApplicationIsNotMembershipAndCanBeCancelled(){long a=user(),b=user();long id=create(a,JoinMode.APPROVAL);act(b,id,Operation.APPLY,null);assertThat(service.status(b).clan()).isNull();assertThat(service.status(b).pendingClanId()).isEqualTo(id);assertThat(service.detail(a,id).applications()).hasSize(1);act(b,id,Operation.CANCEL_APPLICATION,null);assertThat(service.status(b).pendingClanId()).isNull();assertThat(service.status(b).rejoinAvailableAt()).isNull();}
    @Test void onlyOneActiveApplicationAndRejectHasNoCooldown(){long a=user(),b=user(),c=user();long one=create(a,JoinMode.APPROVAL),two=create(b,JoinMode.APPROVAL);act(c,one,Operation.APPLY,null);code(()->act(c,two,Operation.APPLY,null),"CLAN_APPLICATION_EXISTS");act(a,one,Operation.REJECT,c);assertThat(service.status(c).rejoinAvailableAt()).isNull();act(c,two,Operation.APPLY,null);}
    @Test void approvalRechecksLevel(){long a=user(),b=user();long id=create(a,JoinMode.APPROVAL);act(b,id,Operation.APPLY,null);var u=users.findById(b).orElseThrow();u.setAccountLevel(9);users.saveAndFlush(u);code(()->act(a,id,Operation.APPROVE,b),"CLAN_LEVEL_REQUIRED");assertThat(service.status(b).pendingClanId()).isEqualTo(id);}
    @Test void joiningOpenClanClearsOtherApplication(){long a=user(),b=user(),c=user();long one=create(a,JoinMode.APPROVAL),two=create(b,JoinMode.OPEN);act(c,one,Operation.APPLY,null);join(c,two);assertThat(service.detail(a,one).applications()).isEmpty();code(()->act(a,one,Operation.APPROVE,c),"CLAN_APPLICATION_MISSING");}
    @Test void joinModesAreEnforced(){long a=user(),b=user(),c=user();long one=create(a,JoinMode.OPEN),two=create(b,JoinMode.APPROVAL);code(()->act(c,one,Operation.APPLY,null),"CLAN_OPEN_JOIN");code(()->join(c,two),"CLAN_APPROVAL_REQUIRED");}
    @Test void deputyCanApproveAndKickMemberButCannotManageLeaderOrDeputy(){long a=user(),b=user(),c=user(),d=user();long id=create(a,JoinMode.OPEN);join(b,id);join(c,id);act(a,id,Operation.PROMOTE,b);act(a,id,Operation.PROMOTE,c);code(()->act(b,id,Operation.KICK,c),"CLAN_PERMISSION_DENIED");code(()->act(b,id,Operation.KICK,a),"CLAN_PERMISSION_DENIED");code(()->act(b,id,Operation.DEMOTE,c),"CLAN_PERMISSION_DENIED");update(a,id,"공지");act(d,id,Operation.APPLY,null);act(b,id,Operation.APPROVE,d);act(b,id,Operation.KICK,d);assertThat(service.status(d).rejoinAvailableAt()).isEqualTo(now.plus(Duration.ofHours(24)));}
    @Test void memberCannotManageClan(){long a=user(),b=user(),c=user();long id=create(a,JoinMode.OPEN);join(b,id);join(c,id);code(()->act(b,id,Operation.KICK,c),"CLAN_PERMISSION_DENIED");code(()->act(b,id,Operation.PROMOTE,c),"CLAN_PERMISSION_DENIED");code(()->update(b,id,"위조"),"CLAN_PERMISSION_DENIED");}
    @Test void transferMakesExactlyOneLeaderAndFormerLeaderCanLeave(){long a=user(),b=user();long id=create(a,JoinMode.OPEN);join(b,id);code(()->act(a,id,Operation.LEAVE,null),"CLAN_LEADER_MUST_TRANSFER");code(()->act(a,id,Operation.DISBAND,null),"CLAN_NOT_EMPTY");act(a,id,Operation.TRANSFER,b);assertThat(service.status(a).role()).isEqualTo(Role.MEMBER);assertThat(service.status(b).role()).isEqualTo(Role.LEADER);assertThat(service.detail(b,id).members().stream().filter(m->m.role()==Role.LEADER)).hasSize(1);act(a,id,Operation.LEAVE,null);}
    @Test void leaveCooldownBlocksJoinApplyAndCreationUntilExactBoundary(){long a=user(),b=user(),c=user();long id=create(a,JoinMode.OPEN),approval=create(c,JoinMode.APPROVAL);join(b,id);act(b,id,Operation.LEAVE,null);when(clock.now()).thenReturn(now.plusSeconds(86399));code(()->join(b,id),"CLAN_REJOIN_COOLDOWN");code(()->act(b,approval,Operation.APPLY,null),"CLAN_REJOIN_COOLDOWN");code(()->create(b,JoinMode.OPEN),"CLAN_REJOIN_COOLDOWN");when(clock.now()).thenReturn(now.plusSeconds(86400));join(b,id);}
    @Test void soloDisbandPreservesReceiptAndReservesNameWithoutRefund(){long a=user(),b=user();var create=create(name(),JoinMode.APPROVAL);long id=service.command(a,create).clan().clan().clanId();var disband=request(a,id,Operation.DISBAND,null);service.command(a,disband);var replay=service.command(a,disband);assertThat(replay.replayed()).isTrue();assertThat(replay.clan()).isNull();assertThat(replay.accountGold()).isEqualTo(50000);assertThat(replay.rejoinAvailableAt()).isEqualTo(now.plusSeconds(86400));code(()->service.command(b,create(create.name(),JoinMode.OPEN)),"CLAN_NAME_TAKEN");}
    @Test void disbandedApplicationIsInactiveAndCanBeReplaced(){long a=user(),b=user(),c=user();long one=create(a,JoinMode.APPROVAL),two=create(b,JoinMode.APPROVAL);act(c,one,Operation.APPLY,null);act(a,one,Operation.DISBAND,null);assertThat(service.status(c).pendingClanId()).isNull();act(c,two,Operation.APPLY,null);assertThat(service.status(c).pendingClanId()).isEqualTo(two);}
    @Test void staleOfficerRequestAfterDemotionIsDenied(){long a=user(),b=user(),c=user();long id=create(a,JoinMode.OPEN);join(b,id);join(c,id);act(a,id,Operation.PROMOTE,b);var kick=request(b,id,Operation.KICK,c);act(a,id,Operation.DEMOTE,b);code(()->service.command(b,kick),"CLAN_STATE_CHANGED");code(()->act(b,id,Operation.KICK,c),"CLAN_PERMISSION_DENIED");}
    @Test void replayAfterKickDoesNotExposeOldNoticeOrApplications(){long a=user(),b=user(),c=user();long id=create(a,JoinMode.OPEN);var join=request(b,id,Operation.JOIN,null);service.command(b,join);act(a,id,Operation.PROMOTE,b);update(a,id,"비공개 공지");act(c,id,Operation.APPLY,null);assertThat(service.status(b).clan().applications()).hasSize(1);act(a,id,Operation.KICK,b);var replay=service.command(b,join);assertThat(replay.clan()).isNull();assertThat(service.detail(b,id).notice()).isNull();assertThat(service.detail(b,id).applications()).isEmpty();}
    @Test void nonmemberAndMemberCannotSeeApplicantsButMembersSeeNotice(){long a=user(),b=user(),c=user();long id=create(a,JoinMode.OPEN);join(b,id);update(a,id,"멤버 공지");act(c,id,Operation.APPLY,null);assertThat(service.detail(c,id).notice()).isNull();assertThat(service.detail(c,id).applications()).isEmpty();assertThat(service.detail(b,id).notice()).isEqualTo("멤버 공지");assertThat(service.detail(b,id).applications()).isEmpty();assertThat(service.detail(a,id).applications()).hasSize(1);}
    @Test void searchEscapesWildcardsAndBoundsQueries(){long a=user();String key="Search"+UUID.randomUUID().toString().substring(0,5);service.command(a,create(key,JoinMode.OPEN));assertThat(service.search(a,key,0,20).clans()).hasSize(1);assertThat(service.search(a,"%",0,20).clans()).isEmpty();assertThat(service.search(a,"_",0,20).clans()).noneMatch(s->s.name().equals(key));code(()->service.search(a,"x".repeat(21),0,20),"CLAN_INVALID_REQUEST");code(()->service.search(a,"",1001,20),"CLAN_INVALID_REQUEST");code(()->service.search(a,"",0,21),"CLAN_INVALID_REQUEST");}
    @Test void markupControlCharactersAndInvalidNamesAreRejected(){long a=user();for(String value:new String[]{"a","<b>aa</b>","ab\ncd","a".repeat(21),"ab\u202Ecd"})code(()->service.command(a,create(value,JoinMode.OPEN)),"CLAN_INVALID_REQUEST");long id=create(a,JoinMode.OPEN);code(()->update(a,id,"<color=red>공지</color>"),"CLAN_INVALID_REQUEST");}
    @Test void selfTargetAndForeignClanAdministrationAreRejected(){long a=user(),b=user(),c=user();long one=create(a,JoinMode.OPEN),two=create(b,JoinMode.OPEN);join(c,two);code(()->act(a,one,Operation.TRANSFER,a),"CLAN_INVALID_REQUEST");code(()->act(a,two,Operation.KICK,c),"CLAN_PERMISSION_DENIED");}
    @Test void noPrincipalCannotReadOrWriteEvenInLocalProfile() throws Exception {mvc.perform(get("/api/clans/me")).andExpect(status().isUnauthorized());mvc.perform(post("/api/clans/commands").contentType("application/json").content(json.writeValueAsString(create(name(),JoinMode.OPEN)))).andExpect(status().isUnauthorized());}
    @Test void principalRatherThanSpoofedUserIdOwnsCreation() throws Exception {long a=user(),b=user();var u=users.findById(a).orElseThrow();String body=json.writeValueAsString(create(name(),JoinMode.OPEN));body=body.substring(0,body.length()-1)+",\"userId\":"+b+",\"username\":\"other\"}";mvc.perform(post("/api/clans/commands").requestAttr(AccountAccess.PRINCIPAL_ATTRIBUTE,new AccountPrincipal(a,u.getUsername(),"test")).contentType("application/json").content(body)).andExpect(status().isOk()).andExpect(jsonPath("$.userId").value(a));assertThat(service.status(b).clan()).isNull();}
    @Test void guestAndNonGuestNamesMatchExistingProfilePolicy(){long guest=user(),local=user();var localUser=users.findById(local).orElseThrow();localCredentials.saveAndFlush(new LocalDeveloperCredential(localUser.getUsername(),localUser,"unused-test-hash"));long clan=create(guest,JoinMode.OPEN);join(local,clan);var members=service.detail(local,clan).members();assertThat(members).anyMatch(m->m.userId()==guest&&m.displayName().equals("Guest-"+guest));assertThat(members).anyMatch(m->m.userId()==local&&m.displayName().equals(localUser.getUsername()));}
    @Test void authenticatedResponsesAreNeverCached() throws Exception {long a=user();var u=users.findById(a).orElseThrow();var principal=new AccountPrincipal(a,u.getUsername(),"test");long clan=create(a,JoinMode.OPEN);for(String path:new String[]{"/api/clans","/api/clans/me","/api/clans/"+clan})mvc.perform(get(path).requestAttr(AccountAccess.PRINCIPAL_ATTRIBUTE,principal)).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));mvc.perform(post("/api/clans/commands").requestAttr(AccountAccess.PRINCIPAL_ATTRIBUTE,principal).contentType("application/json").content(json.writeValueAsString(request(a,clan,Operation.DISBAND,null)))).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));}
    @Test void policyIsAuthenticatedAndUsesServerConfiguration() throws Exception {long a=user();var u=users.findById(a).orElseThrow();mvc.perform(get("/api/clans/policy")).andExpect(status().isUnauthorized());mvc.perform(get("/api/clans/policy").requestAttr(AccountAccess.PRINCIPAL_ATTRIBUTE,new AccountPrincipal(a,u.getUsername(),"test"))).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.creationGold").value(50000)).andExpect(jsonPath("$.minimumLevel").value(10)).andExpect(jsonPath("$.rejoinCooldownSeconds").value(86400));assertThat(service.status(a).accountLevel()).isEqualTo(10);}
    @Test void changedCreationQuoteCannotSpendGold(){long a=user();var old=create(name(),JoinMode.OPEN);var wrong=new Command(old.requestId(),old.operation(),null,null,null,old.name(),old.description(),null,old.joinMode(),49999);code(()->service.command(a,wrong),"CLAN_QUOTE_CHANGED");assertThat(service.status(a).accountGold()).isEqualTo(100000);assertThat(service.status(a).clan()).isNull();var right=new Command(old.requestId(),old.operation(),null,null,null,old.name(),old.description(),null,old.joinMode(),50000);assertThat(service.command(a,right).accountGold()).isEqualTo(50000);assertThat(service.command(a,right).replayed()).isTrue();}
    @Test void nullNewQuotePreservesLegacyReceiptFingerprint() throws Exception {long a=user();var c=create(name(),JoinMode.OPEN);String legacy="{\"requestId\":\""+c.requestId()+"\",\"operation\":\"CREATE\",\"clanId\":null,\"targetUserId\":null,\"expectedRevision\":null,\"name\":\""+c.name()+"\",\"description\":\"소개\",\"notice\":null,\"joinMode\":\"OPEN\"}";assertThat(json.writeValueAsString(c)).isEqualTo(legacy);service.command(a,c);String hash=java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(legacy.getBytes(java.nio.charset.StandardCharsets.UTF_8)));assertThat(receipts.findByUserIdAndRequestId(a,c.requestId()).orElseThrow().getFingerprint()).isEqualTo(hash);assertThat(service.command(a,json.readValue(legacy,Command.class)).replayed()).isTrue();}
}
